import {icon} from './icons.js';
import {init,request,isDemo,config} from './adapter.js';

const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusNames={new:'Новое',processing:'В работе',review:'На проверке',manual:'Нужен сотрудник',approved:'Подтверждено',escalated:'Передано сотруднику'};
const categoryNames={delivery:'Доставка',cancellation:'Отмена заказа',returns:'Возврат',damage:'Повреждение',payment:'Оплата',other:'Другой вопрос'};
const reasonNames={orders_unavailable:'API заказов не ответил вовремя. Повторите анализ после восстановления сервиса.',order_not_found:'Заказ не найден. Уточните номер заказа у клиента.',invalid_order_data:'API вернул некорректные данные заказа. Требуется проверка интеграции.',missing_order_id:'В обращении нет номера заказа. Уточните его у клиента.',ownership_review:'Имя клиента не совпадает с данными заказа. Проверьте принадлежность заказа.',missing_sources:'Не найдены необходимые действующие правила. Нельзя подготовить проверенный ответ.',conflicting_documents:'Обнаружены одновременно действующие версии правил. Устраните противоречие в базе знаний.',invalid_model_output:'Модель дважды вернула недопустимый результат. Черновик заблокирован.',model_unavailable:'Сервис модели недоступен. Можно повторить анализ позднее.',model_not_configured:'Не настроены модель или ключ API. Проверьте конфигурацию сервера.',damage_requires_review:'Повреждённый товар требует проверки фотографий и решения сотрудника.',payment_requires_review:'Платёжные данные нужно проверить в платёжной системе. Данных заказа недостаточно.',action_requires_review:'Запрошенное действие требует отдельного согласования сотрудником.',return_eligibility_review:'Нужно проверить дату получения и допустимость возврата.',unsupported_intent:'Обращение выходит за рамки доступных правил. Требуется сотрудник.',untrusted_instructions:'В сообщении обнаружена попытка изменить инструкции. Требуется ручная проверка.',workflow_failed:'Обработка прервана. Проверьте журнал сервиса и повторите анализ.',validation_failed:'Ответ не прошёл обязательные проверки. Требуется сотрудник.'};
const stepNames={classify:'Классификация обращения',orders_api:'Проверка заказа через API',retrieval:'Поиск действующих правил',generate:'Подготовка ответа',validate:'Проверка фактов и действий'};
const state={page:'tickets',filter:'all',query:'',selected:'SO-1284',tab:'draft',tickets:[],docs:[],metrics:{},evaluation:{status:'not_run'},detail:null,busy:false,drafts:{},sort:'newest',docQuery:'',showArchived:false};
let creationKey=null;
const initials=name=>name.split(' ').map(x=>x[0]).slice(0,2).join('');
const badge=(status)=>`<span class="badge badge-${esc(status)}">${icon(status==='review'?'spark':status==='approved'?'check':status==='manual'||status==='escalated'?'human':status==='processing'?'clock':'inbox')}${statusNames[status]||esc(status)}</span>`;
const fmtDate=(value,opts={day:'numeric',month:'short'})=>value?new Date(value).toLocaleDateString('ru-RU',opts):'—';
const ms=value=>value==null?'—':value<1000?`${Math.round(value)} мс`:`${(value/1000).toFixed(1)} с`;
const channelIcon=c=>c==='email'?'mail':c==='chat'?'chat':'globe';
const pages={overview:'Обзор',tickets:'Обращения',knowledge:'База знаний',quality:'AI Release Guard',monitoring:'Мониторинг',settings:'Настройки'};

function toast(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'warning':'checkcircle')+`<span>${esc(text)}</span>`;$('#toasts').appendChild(el);setTimeout(()=>el.remove(),5000)}
function fail(e){const names={revision_conflict:'Обращение уже изменилось. Обновите страницу.',invalid_api_key:'Нужен ключ доступа. Введите его в настройках.',analysis_in_progress:'Анализ уже выполняется. Дождитесь результата.',fault_injection_disabled:'Сценарии сбоев отключены в конфигурации сервера.'};toast(names[e.message]||e.message||'Не удалось выполнить запрос',true)}
async function reload(){const [tickets,docs,metrics,evaluation]=await Promise.all([request('/tickets'),request('/knowledge'),request('/metrics'),request('/evaluation')]);Object.assign(state,{tickets,docs,metrics,evaluation});if(!tickets.some(t=>t.id===state.selected))state.selected=tickets[0]?.id;state.detail=state.selected?await request('/tickets/'+state.selected):null;}
function sidebar(){return `<aside class="sidebar"><a class="brand" href="#tickets" aria-label="SupportOps AI · главная"><span class="brand-mark">${icon('logo')}</span><span>SupportOps</span><em>AI</em></a><div class="workspace"><span class="store-mark">${icon('leaf')}</span><div><strong>Листва</strong><small>Рабочее пространство</small></div>${icon('down')}</div><p class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</p><nav>${[['overview','grid'],['tickets','inbox'],['knowledge','book']].map(([p,i])=>nav(p,i)).join('')}<div class="nav-separator"></div><p class="nav-label">КАЧЕСТВО И СИСТЕМА</p>${[['quality','shield'],['monitoring','activity']].map(([p,i])=>nav(p,i)).join('')}</nav><div class="sidebar-bottom">${nav('settings','settings')}<div class="system-note"><b>${icon('shield')}Человек принимает решение</b>Каждый ответ проходит проверку сотрудником перед использованием.<a href="#quality">Как устроена проверка ${icon('arrow')}</a></div><div class="profile"><div class="avatar">КБ</div><div><strong>Ксения</strong><small>Сотрудник поддержки</small></div>${icon('down')}</div></div></aside>`}
function nav(p,i){return `<a href="#${p}" class="nav-item ${state.page===p?'active':''}" aria-label="${pages[p]}" ${state.page===p?'aria-current="page"':''}>${icon(i)}<span>${pages[p]}</span>${p==='tickets'?`<b class="nav-count">${state.tickets.filter(t=>!['approved','escalated'].includes(t.status)).length}</b>`:''}</a>`}
function render(){document.title=`SupportOps AI · ${pages[state.page]}`;$('#app').innerHTML=`<div class="app-shell">${sidebar()}<main class="main"><header class="topbar"><div class="breadcrumbs"><span>Рабочее пространство</span>${icon('chevron')}<b>${pages[state.page]}</b></div><div class="top-actions"><span class="system-status"><i class="status-dot"></i>${isDemo?'Демонстрационный режим':'Рабочее пространство'}</span><i class="top-divider"></i><button class="icon-btn" data-action="activity" aria-label="Последние события">${icon('bell')}</button><div class="avatar" aria-label="Профиль Ксении">КБ</div></div></header>${isDemo?`<div class="demo-banner"><span>${icon('info')}Интерактивное демо · синтетические данные · изменения сохраняются в этом браузере</span><button data-action="demo-info">О демо ${icon('arrow')}</button></div>`:''}<div class="content">${pageContent()}</div></main></div>`;}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function metric(label,value,sub,ic,highlight=false,tag=''){return `<div class="metric ${highlight?'metric-highlight':''}"><div class="metric-top"><span>${label}</span>${icon(ic)}</div><div class="metric-value"><strong>${value}</strong>${tag?`<span class="mini-tag">${tag}</span>`:''}</div><div class="metric-label">${sub}</div></div>`}
function metricsRow(){const m=state.metrics;return `<div class="metrics-row">${metric('Всего обращений',m.total??0,'В рабочем пространстве','inbox')}${metric('Готовы к проверке',m.review??0,'Черновики ожидают решения','spark',true,'AI + человек')}${metric('Требуют внимания',m.manual??0,'Ручная обработка и эскалации','human')}${metric('Время подготовки · p50',ms(m.p50_ms),isDemo?'Демо: задержка не измеряется':`По ${m.analyzed??0} обработанным обращениям`,'clock')}</div>`}
function pageContent(){switch(state.page){case'tickets':return ticketsPage();case'knowledge':return knowledgePage();case'quality':return qualityPage();case'monitoring':return monitoringPage();case'overview':return overviewPage();case'settings':return settingsPage();}}
function ticketsPage(){return `${heading('Обращения','Помогайте клиентам быстрее. Каждое решение — под вашим контролем.',`<span class="date-label">${icon('clock')}${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</span><button class="btn btn-primary" data-action="new">${icon('plus')}Новое обращение</button>`)}${metricsRow()}<div class="queue-toolbar"><div class="filter-tabs" role="group" aria-label="Фильтр обращений">${[['all','Все обращения'],['review','На проверке'],['manual','Нужен сотрудник'],['approved','Готово']].map(([id,label])=>`<button class="filter-tab ${state.filter===id?'active':''}" data-filter="${id}" aria-pressed="${state.filter===id}">${label}<span>${filteredByStatus(id).length}</span></button>`).join('')}</div><div class="toolbar-right"><label class="search-wrap">${icon('search')}<input id="ticket-search" aria-label="Поиск обращений" placeholder="Поиск обращений…" value="${esc(state.query)}"><kbd>⌘ K</kbd></label><button class="btn" data-action="sort" title="Поменять порядок сортировки">${icon('filter')}<span>${state.sort==='newest'?'Новые':'Приоритет'}</span></button></div></div><section class="workbench" aria-label="Рабочая область обращений"><div class="ticket-list"><div class="list-heading"><b>Очередь обращений</b>${icon('down')}</div><div id="ticket-items">${ticketItems()}</div></div><div class="ticket-detail" id="ticket-detail">${detailContent()}</div></section><div class="bottom-line"><span><i class="status-dot"></i>${isDemo?'Демо магазина «Листва»':'Синтетический магазин «Листва»'} · данные без персональной информации</span><span><kbd>N</kbd> Новое обращение <kbd>⌘ K</kbd> Поиск</span></div>`}
function filteredByStatus(id){return state.tickets.filter(t=>id==='all'||(id==='manual'?['manual','escalated'].includes(t.status):id==='approved'?t.status==='approved':t.status===id))}
function filteredTickets(){const q=state.query.toLowerCase();let rows=filteredByStatus(state.filter).filter(t=>[t.id,t.customer,t.subject,t.message,t.order_id].some(v=>String(v||'').toLowerCase().includes(q)));if(state.sort==='priority')rows.sort((a,b)=>(b.priority==='high')-(a.priority==='high'));return rows;}
function ticketItems(){const rows=filteredTickets();return rows.length?rows.map((t,i)=>`<button class="ticket-item ${t.id===state.selected?'selected':''}" data-ticket="${esc(t.id)}" aria-label="${esc(t.subject)} · ${esc(t.customer)}" aria-pressed="${t.id===state.selected}"><div class="ticket-item-top"><div class="avatar" style="background:${['#eee8df','#e7edde','#e2e9ee','#ece4e7'][state.tickets.indexOf(t)%4]}">${esc(initials(t.customer))}</div><span class="ticket-name">${esc(t.customer)}</span><time class="ticket-time">${new Date(t.created_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time></div><div class="ticket-subject">${esc(t.subject)}</div><div class="ticket-snippet">${esc(t.message)}</div><div class="ticket-item-bottom">${badge(t.status)}<span class="ticket-channel">${icon(channelIcon(t.channel))}${esc(t.id)}</span></div></button>`).join(''):`<div class="empty">${icon('search')}Обращения не найдены<button class="btn" data-action="clear-search">Сбросить фильтры</button></div>`}
function detailContent(){const t=state.detail;if(!t)return `<div class="empty">Выберите обращение в очереди</div>`;const r=t.result;return `<div class="detail-top"><div class="ticket-id">${esc(t.id)}<span>•</span>${icon(channelIcon(t.channel))}${{email:'Email',chat:'Чат',web:'Веб-форма'}[t.channel]}</div><div class="detail-top-right">${t.priority==='high'?'<span class="priority"><i class="priority-dot"></i>Высокий приоритет</span>':''}<button class="icon-btn" data-action="copy-id" title="Скопировать номер обращения" aria-label="Скопировать номер обращения">${icon('copy')}</button></div></div><div class="detail-grid"><div class="conversation"><h2 class="ticket-title">${esc(t.subject)}</h2><div class="category-line">${(r?.categories?.length?r.categories:[t.category]).map(c=>`<span class="category-tag">${categoryNames[c]||esc(c)}</span>`).join('')}${t.order_id?`<span class="category-tag">Заказ №${esc(t.order_id)}</span>`:''}</div><article class="message-card"><div class="message-head"><div class="avatar">${esc(initials(t.customer))}</div><div><strong>${esc(t.customer)}</strong><small>${esc(t.email||'Клиент магазина')}</small></div><time class="message-time">${fmtDate(t.created_at)}</time></div><p>${esc(t.message).replace(/\n/g,'<br>')}</p></article><section class="ai-panel"><div class="ai-heading"><div class="ai-heading-title">${icon('spark')}Ассистент SupportOps</div><span class="badge">${isDemo?'Демонстрация':config.provider==='baseline'?'Проверяемый baseline':'LLM + проверка'}</span></div>${state.busy?`<div class="loading-line"></div><div class="empty">${icon('refresh','spinner')}Проверяем заказ и собираем источники…</div>`:!r?emptyDraft():analysisContent(t,r)}</section>${reviewActions(t)}<p class="review-caption">${icon('shield')}Ответ не отправляется клиенту автоматически</p></div>${contextPanel(t,r)}</div>`}
function emptyDraft(){return `<div class="empty"><div class="waiting-illustration">${icon('spark')}</div><strong>От обращения — к проверенному ответу</strong>Ассистент проверит заказ, найдёт правила<br>и подготовит черновик с источниками.<br><button class="btn btn-primary" data-action="analyze">${icon('spark')}Подготовить ответ</button></div>`}
function analysisContent(t,r){return `<div class="detail-tabs" role="tablist" aria-label="Результат анализа">${[['draft','Ответ'],['sources','Источники'],['workflow','Workflow'],['history','История']].map(([id,label])=>`<button role="tab" aria-selected="${state.tab===id}" class="detail-tab ${state.tab===id?'active':''}" data-tab="${id}">${label}${id==='sources'?`<span>${r.sources?.length||0}</span>`:''}</button>`).join('')}</div>${state.tab==='draft'?draftContent(t,r):state.tab==='sources'?sourcesContent(r):state.tab==='workflow'?workflowContent(r):historyContent(t)}`}
function draftContent(t,r){if(r.reason)return `<div class="manual-box">${icon('human')}<b>Нужна помощь сотрудника</b><p>${esc(reasonNames[r.reason]||r.reason)}</p><p style="margin-top:10px;font-size:10px">Проверенный черновик не создан. Доступные данные и источники сохранены в карточке.</p>${!['approved','escalated'].includes(t.status)?`<button class="btn" data-action="analyze">${icon('refresh')}Повторить анализ</button>`:''}</div>`;const latest=(t.reviews||[]).findLast?.(x=>x.decision==='approve');const text=state.drafts[t.id]??latest?.text??r.draft;return `<div class="draft-body"><div class="verified-note">${icon('checkcircle')}Факты и правила проверены · требуется ваше решение</div>${state.drafts[t.id]&&state.drafts[t.id]!==r.draft?'<div class="revision-note">Текст отредактирован сотрудником. Проверьте изменённые факты перед подтверждением.</div>':''}<label class="sr-only" for="draft-text">Черновик ответа клиенту</label><textarea id="draft-text" class="draft-text" ${t.status==='approved'||t.status==='escalated'?'readonly':''}>${esc(text||'')}</textarea><div class="draft-footer"><span>${icon('clock')}${ms(r.duration_ms)}${isDemo?' · симуляция':''}</span><span>${t.status==='approved'?'Подтверждён сотрудником':'Можно отредактировать перед подтверждением'}<button class="icon-btn" data-action="copy-draft" aria-label="Скопировать ответ" title="Скопировать ответ">${icon('copy')}</button></span></div></div><div class="sources-inline">Основано на${(r.sources||[]).slice(0,3).map((d,i)=>`<button class="source-chip" data-doc="${esc(d.id)}">${icon('file')}${i+1}. ${esc(d.title)}</button>`).join('')}${r.order?`<span class="source-chip">${icon('box')}API заказа №${esc(r.order.id)}</span>`:''}</div>`}
function sourcesContent(r){return `<div class="draft-body">${r.order?`<div class="source-card" data-action="order-info"><h4>${icon('box')} API магазина · заказ №${esc(r.order.id)}</h4><p>Статус, перевозчик, трек-номер и состав заказа получены из ${isDemo?'синтетического набора данных':'API заказов'}.</p><div class="source-meta"><span>Авторитетный источник статуса заказа</span></div></div>`:''}${(r.sources||[]).map(d=>`<button class="source-card" data-doc="${esc(d.id)}" style="display:block;width:100%;text-align:left"><h4>${icon('file')} ${esc(d.title)}</h4><p>${esc(d.text)}</p><div class="source-meta"><span>v${esc(d.version)}</span><span>С ${fmtDate(d.effective_from)}</span><span>${icon('external')} Открыть</span></div></button>`).join('')||'<div class="empty">Источники пока не найдены</div>'}</div>`}
function workflowContent(r){return `<div class="draft-body">${(r.steps||[]).map((s,i)=>`<div class="workflow-node">${icon(s.status==='error'?'warning':'checkcircle')}<span>${stepNames[s.name]||esc(s.name)}</span><small>${ms(s.duration_ms)}</small></div>`).join('')}<div class="workflow-node">${icon('human')}<span>Решение сотрудника</span><small>${['approved','escalated'].includes(state.detail.status)?'Завершено':'Ожидается'}</small></div><p class="context-note">${isDemo?'Шаги воспроизведены в браузере. Это не серверные traces.':'Состояние сохранено в persistent checkpointer LangGraph.'}</p><pre class="code-block">${esc(JSON.stringify(r.manifest||{},null,2))}</pre><button class="btn" data-action="export-trace">${icon('download')}Скачать результат JSON</button></div>`}
function historyContent(t){return `<div class="draft-body"><div class="history-event">Обращение создано<small>${fmtDate(t.created_at,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})}</small></div>${t.result?`<div class="history-event">${t.result.reason?'Передано на ручную проверку':'Подготовлен черновик'}<small>Ревизия ${t.revision} · ${esc(t.result.manifest?.model||'workflow')}</small></div>`:''}${(t.reviews||[]).map(r=>`<div class="history-event">${r.decision==='approve'?'Ответ подтверждён':'Обращение эскалировано'}<small>${fmtDate(r.created_at,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · ${esc(r.actor||'Сотрудник')}</small>${r.note?`<p>${esc(r.note)}</p>`:''}</div>`).join('')}</div>`}
function reviewActions(t){if(t.status==='approved')return `<div class="completed-box">${icon('checkcircle')}Ответ подтверждён. Его можно скопировать для отправки клиенту.</div>`;if(t.status==='escalated')return `<div class="completed-box">${icon('human')}Обращение передано сотруднику. Решение сохранено в истории.</div>`;if(!t.result||state.busy)return '';return `<div class="review-actions">${t.status==='review'?`<button class="btn btn-primary" data-action="approve">${icon('check')}Подтвердить ответ</button>`:''}<button class="btn" data-action="escalate">${icon('human')}Передать сотруднику</button>${config.faults_enabled?`<button class="icon-btn" data-action="faults" title="Проверить сценарий сбоя" aria-label="Проверить сценарий сбоя">${icon('code')}</button>`:''}</div>`}
function contextPanel(t,r){const o=r?.order;const statuses={delayed:'Доставка задерживается',shipped:'В пути',processing:'На сборке',delivered:'Доставлен',cancelled:'Отменён'};return `<aside class="context-panel"><div class="context-section"><h3 class="context-heading">${icon('box')}Детали заказа</h3>${o?`<div class="order-title">№${esc(o.id)}<button class="icon-btn" data-action="order-info" aria-label="Посмотреть данные заказа">${icon('external')}</button></div><span class="badge ${o.status==='delayed'?'badge-manual':'badge-review'}">${icon('truck')}${statuses[o.status]}</span>${o.items.map(item=>`<div class="order-product"><div class="product-icon">${icon('box')}</div><div><b>${esc(item.title)}</b><small>${item.quantity} шт. · магазин Листва</small></div></div>`).join('')}<div class="kv"><span>Сумма заказа</span><strong>${o.total.toLocaleString('ru-RU')} ₽</strong></div><div class="kv"><span>Дата заказа</span><strong>${fmtDate(o.placed_at)}</strong></div><div class="kv"><span>Плановая доставка</span><strong>${fmtDate(o.expected_at)}</strong></div><div class="kv"><span>Перевозчик</span><strong>${esc(o.carrier)}</strong></div>${o.tracking?`<div class="kv"><span>Трек-номер</span><strong>${esc(o.tracking)}</strong></div>`:''}<p class="context-note">${icon('link')} ${isDemo?'Синтетические данные магазина':'Получено через API магазина'}</p>`:`<div class="context-note">${t.order_id?`Заказ №${esc(t.order_id)}`:'Номер заказа не указан'}<br>Данные появятся после анализа обращения.</div>`}</div><div class="context-section"><h3 class="context-heading">${icon('human')}О клиенте</h3><div class="context-customer"><div class="avatar">${esc(initials(t.customer))}</div><div><strong>${esc(t.customer)}</strong><small>${esc(t.email||'Контакт не указан')}</small></div></div><div class="kv"><span>Канал</span><strong>${{email:'Email',chat:'Чат',web:'Веб-форма'}[t.channel]}</strong></div><div class="kv"><span>Магазин</span><strong>Листва · демо</strong></div></div><div class="context-section"><h3 class="context-heading">${icon('shield')}Проверка ответа</h3>${r?.checks?.length?`<div class="check-list">${r.checks.map(c=>`<div class="check-item ${c.passed?'':'failed'}">${icon(c.passed?'checkcircle':'warning')}<span>${esc(c.label)}</span></div>`).join('')}</div>`:'<p class="context-note">Проверки выполняются при подготовке ответа.</p>'}${r?.trace_id?`<button class="trace-link" data-action="export-trace">${icon('activity')}<code>trace: ${esc(r.trace_id.slice(0,16))}…</code>${icon('external')}</button>`:''}</div></aside>`}

function overviewPage(){const m=state.metrics;return `${heading('Всё под контролем','Очередь, качество ответов и состояние рабочего процесса.',`<button class="btn btn-primary" data-action="new">${icon('plus')}Новое обращение</button>`)}${metricsRow()}<div class="section-grid"><section class="panel"><h2>Очередь по статусам</h2><p>Текущее состояние всех обращений</p>${['new','review','manual','approved','escalated'].map(status=>{let count=state.tickets.filter(t=>t.status===status).length;return `<div class="bar-row"><span>${statusNames[status]}</span><div class="bar-track"><div class="bar-fill" style="width:${m.total?count/m.total*100:0}%"></div></div><b>${count}</b></div>`}).join('')}</section><section class="panel"><h2>От вопроса к решению</h2><p>Каждый этап можно проверить и объяснить</p>${[['inbox','Получить обращение','Валидация входных данных и защита от дублей'],['box','Собрать контекст','Заказ из API и действующие правила магазина'],['spark','Подготовить ответ','Только проверенные факты и допустимые действия'],['human','Проверить с человеком','Редактирование, подтверждение или эскалация']].map(([ic,title,sub])=>`<div class="workflow-node">${icon(ic)}<span>${title}<small style="display:block;margin-top:4px">${sub}</small></span></div>`).join('')}</section></div><section class="panel"><h2>Требуют внимания</h2><p>Обращения, где решение остаётся за сотрудником</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Обращение</th><th>Клиент</th><th>Статус</th><th></th></tr></thead><tbody>${state.tickets.filter(t=>!['approved','escalated'].includes(t.status)).slice(0,5).map(t=>`<tr><td><strong>${esc(t.subject)}</strong><br><code>${esc(t.id)}</code></td><td>${esc(t.customer)}</td><td>${badge(t.status)}</td><td><button class="btn" data-open-ticket="${esc(t.id)}">Открыть ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section>`}
function knowledgePage(){const day=new Date().toISOString().slice(0,10);const active=d=>d.effective_from<=day&&(!d.effective_to||d.effective_to>day);const docs=state.docs.filter(d=>(state.showArchived||active(d))&&[d.title,d.text].some(v=>v.toLowerCase().includes(state.docQuery.toLowerCase())));return `${heading('База знаний','Проверяемые правила магазина. С источником, версией и датой действия.',`<button class="btn" data-action="export-knowledge">${icon('download')}Экспорт JSON</button>`)}<div class="info-strip">${icon('shield')}При подготовке ответа используются только действующие версии. Архивное правило возврата на 14 дней исключено из поиска.</div><div class="queue-toolbar"><div class="filter-tabs"><button class="filter-tab ${!state.showArchived?'active':''}" data-archive="false">Действующие <span>${state.docs.filter(active).length}</span></button><button class="filter-tab ${state.showArchived?'active':''}" data-archive="true">Все версии <span>${state.docs.length}</span></button></div><label class="search-wrap">${icon('search')}<input id="doc-search" value="${esc(state.docQuery)}" placeholder="Поиск по правилам…" aria-label="Поиск по базе знаний"></label></div><div id="document-cards" class="document-grid">${docs.map(d=>`<button class="document-card" data-doc="${esc(d.id)}"><span class="document-icon">${icon('file')}</span><h3>${esc(d.title)}</h3><p>${esc(d.text)}</p><div class="source-meta"><span>v${esc(d.version)}</span><span>С ${fmtDate(d.effective_from)}</span><span class="badge ${active(d)?'badge-review':''}">${active(d)?'Действует':'Архив'}</span></div></button>`).join('')||'<div class="empty">Ничего не найдено</div>'}</div>`}
function qualityPage(){const e=state.evaluation;const ready=e.status==='passed'||e.status==='failed';return `${heading('AI Release Guard','Изменения проходят проверку до выпуска. Качество подтверждается данными.',`<button class="btn" data-action="export-eval">${icon('download')}Скачать отчёт</button>`)}<div class="info-strip">${icon('info')}${isDemo?'Снимок локального evaluation. Демонстрация не запускает настоящую модель.':'Evaluation запускается отдельной командой и проверяется в CI перед сборкой.'}</div>${ready?`<div class="metrics-row">${metric('Фактическая корректность',`${Math.round(e.metrics.factual_accuracy*100)}%`,'Проверка статусов, фактов и источников','checkcircle',true)}${metric('Классификация · macro-F1',e.metrics.macro_f1.toFixed(2),'По ручной разметке синтетического набора','inbox')}${metric('Recall ручной обработки',`${Math.round(e.metrics.escalation_recall*100)}%`,'Случаи, которые нельзя отвечать автоматически','human')}${metric('Задержка · p95',ms(e.metrics.p95_ms),`${e.cases} кейсов · последовательная нагрузка`,'clock')}</div><div class="section-grid"><section class="panel"><h2>Результат проверки релиза</h2><p>Набор ${esc(e.dataset_version)} · ${esc(e.split)}</p><div class="quality-score"><div class="score-ring"><b>${e.passed}/${e.cases}</b><small>кейсов пройдено</small></div><div><h3>${e.status==='passed'?'Проверки пройдены':'Выпуск заблокирован'}</h3><p>Модель: ${esc(e.model)}<br>${fmtDate(e.created_at,{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'})}<br>${e.live?'Live-запуск с внешней моделью':'Детерминированный baseline · без LLM-затрат'}</p></div></div><button class="btn" data-action="eval-info">${icon('terminal')}Как повторить проверку</button></section><section class="panel"><h2>Что проверяет guard</h2><p>Ошибки блокируют pipeline</p><div class="check-list">${['Применяется действующее правило возврата','Отправленный заказ не отменяется автоматически','Недоступность API приводит к ручной обработке','Модель не добавляет факты вне источников','Повторное подтверждение не создаёт дубль'].map(c=>`<div class="check-item">${icon('checkcircle')}<span>${c}</span></div>`).join('')}</div><div class="notice-card">${icon('info')}Эти метрики относятся к синтетическому набору. Польза для сотрудника и качество реальной модели требуют отдельного исследования.</div></section></div><section class="panel"><h2>Результаты сценариев</h2><p>Изолированный ${esc(e.split)}-набор · seed ${e.seed}</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Сценарий</th><th>Ожидаемая категория</th><th>Результат</th><th>Время</th></tr></thead><tbody>${(e.results||[]).map(r=>`<tr><td>${esc(r.id)}<br><code>${esc(r.description)}</code></td><td>${(r.expected_categories||[]).map(c=>categoryNames[c]).join(', ')}</td><td><span class="badge ${r.passed?'badge-review':'badge-manual'}">${icon(r.passed?'check':'warning')}${r.passed?'Пройден':'Ошибка'}</span></td><td>${ms(r.duration_ms)}</td></tr>`).join('')}</tbody></table></div></section>`:`<section class="panel"><div class="empty">${icon('shield')}<strong>Проверка ещё не запущена</strong>Отчёт появится после выполнения evaluation.<pre class="code-block">python -m eval.run --split holdout</pre><button class="btn" data-action="refresh">${icon('refresh')}Обновить</button></div></section>`}`}
function monitoringPage(){const m=state.metrics;return `${heading('Мониторинг','Проследите путь обращения и найдите причину сбоя.',`<button class="btn" data-action="refresh">${icon('refresh')}Обновить</button>`)}${isDemo?`<div class="info-strip">${icon('info')}В демо показана структура workflow. Реальные задержки и traces доступны в локальном приложении.</div>`:''}<div class="metrics-row">${metric('Обработано обращений',m.analyzed??0,'Включая ручную обработку','activity')}${metric('Задержка · p95',ms(m.p95_ms),'Последовательные запуски в этом окружении','clock')}${metric('Токены LLM',(m.tokens??0).toLocaleString('ru-RU'),config.provider==='baseline'?'Baseline не вызывает LLM':'Входящие и исходящие токены','spark')}${metric('Расход LLM',`$${(m.cost_usd||0).toFixed(4)}`,'Инфраструктура оплачивается отдельно','grid')}</div><section class="panel"><h2>Последние обработки</h2><p>Один trace ID связывает все шаги одного запуска</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Обращение / trace</th><th>Статус</th><th>Причина / модель</th><th>Задержка</th><th></th></tr></thead><tbody>${(m.runs||[]).map(r=>`<tr><td><strong>${esc(r.ticket_id)}</strong><br><code>${esc(r.trace_id?.slice(0,18)||'—')}</code></td><td>${badge(r.status)}</td><td style="max-width:330px">${esc(r.reason?reasonNames[r.reason]||r.reason:r.manifest?.model||'—')}</td><td>${ms(r.duration_ms)}</td><td><button class="btn" data-open-ticket="${esc(r.ticket_id)}" data-workflow="true">Trace ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5">Запустите анализ обращения, чтобы увидеть workflow.</td></tr>'}</tbody></table></div></section><div class="section-grid"><section class="panel"><h2>Воспроизвести сбой</h2><p>Безопасные сценарии на синтетическом обращении</p>${[['orders_timeout','API заказов не отвечает','Ограниченный timeout → ручная обработка'],['invalid_model','Модель вернула неверный результат','Две попытки → проверенный отказ'],['missing_sources','Нет необходимых правил','Нет источников → нет черновика']].map(([id,title,sub])=>`<div class="setting-row"><div><h3>${title}</h3><p>${sub}</p></div><button class="btn" data-fault="${id}" ${!config.faults_enabled?'disabled':''}>${icon('play')}Запустить</button></div>`).join('')}</section><section class="panel"><h2>Диагностика и восстановление</h2><p>Локально и в облачном окружении</p><div class="modal-prose">OpenTelemetry связывает API, retrieval, генерацию и проверку. Экспорт настраивается через OTLP.<br><br>После сбоя восстановите зависимость и повторите анализ. Подтверждённые обращения защищены от повторной обработки.</div><button class="btn" data-action="runbook" style="margin-top:18px">${icon('book')}Открыть runbook</button></section></div>`}
function settingsPage(){return `${heading('Настройки','Конфигурация окружения, модели и доступа.')}<section class="panel"><h2>Рабочее пространство</h2><p>Демонстрационный интернет-магазин</p>${[['Название магазина','Синтетический набор данных, доступный для публикации','Листва'],['Режим приложения',isDemo?'Состояние хранится в localStorage этого браузера':'Обращения, review и checkpoints сохраняются на сервере',isDemo?'Browser demo':'FastAPI'],['Провайдер модели','Меняется на сервере через MODEL_PROVIDER',config.provider],['Версия приложения','Код, промпт и документы фиксируются в результате анализа',config.version]].map(([a,b,c])=>`<div class="setting-row"><div><h3>${a}</h3><p>${b}</p></div><code>${esc(c)}</code></div>`).join('')}</section>${!isDemo?`<section class="panel"><h2>Доступ к API</h2><p>Ключ хранится только в sessionStorage и передаётся серверу в заголовке X-API-Key.</p><form id="auth-form"><label class="field">Ключ доступа<input type="password" name="key" placeholder="APP_API_KEY" autocomplete="off" value="${esc(sessionStorage.getItem('supportops-api-key')||'')}"></label><button class="btn btn-primary" type="submit">Сохранить и подключиться</button></form></section>`:''}<section class="panel"><h2>Подключение внешней модели</h2><p>Секреты задаются через окружение сервера или Secrets Manager, без передачи в браузер.</p><pre class="code-block">MODEL_PROVIDER=openai_compatible
LLM_BASE_URL=https://your-provider.example/v1
LLM_MODEL=your-model-id
LLM_API_KEY=…</pre><div class="notice-card">${icon('shield')}Модель выбирает идентификаторы проверенных фактов и тон. Текст фактов и допустимые действия формируются кодом из API заказа и действующих правил.</div></section>${isDemo?`<section class="panel"><h2>Данные демонстрации</h2><p>Сброс удалит только локальные изменения этого демо в текущем браузере.</p><button class="btn" data-action="reset-demo">${icon('refresh')}Сбросить демо</button></section>`:''}`}

function modal(title,subtitle,body,wide=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('x')}</button></div><p>${esc(subtitle)}</p>${body}</section></div>`;setTimeout(()=>$('#overlay input, #overlay textarea, #overlay button')?.focus(),30)}
function closeModal(){$('#overlay').innerHTML=''}
function newTicket(){creationKey=crypto.randomUUID();modal('Новое обращение','Создайте обращение клиента магазина «Листва».',`<form id="ticket-form"><div class="form-grid"><label class="field">Имя клиента<input name="customer" required minlength="2" maxlength="100" placeholder="Анна Смирнова"></label><label class="field">Email<input name="email" type="email" placeholder="customer@example.test" maxlength="160"></label></div><div class="form-grid"><label class="field">Номер заказа<input name="order_id" inputmode="numeric" pattern="[0-9]{4,12}" placeholder="1042"></label><label class="field">Канал<select name="channel"><option value="email">Email</option><option value="chat">Чат</option><option value="web">Веб-форма</option></select></label></div><label class="field">Тема<input name="subject" required minlength="3" maxlength="180" placeholder="Например, задерживается доставка"></label><label class="field">Сообщение клиента<textarea name="message" required minlength="10" maxlength="5000" placeholder="Опишите вопрос клиента…"></textarea></label><label class="field">Приоритет<select name="priority"><option value="normal">Обычный</option><option value="high">Высокий</option></select></label><div class="notice-card">${icon('info')}Тестовые заказы: 1042–1049. Имя клиента должно соответствовать заказу. Для заказа 1042 используйте «Анна Смирнова».</div><div class="modal-actions"><button class="btn" type="button" data-action="fill-example">Заполнить пример</button><button class="btn btn-primary" type="submit">${icon('plus')}Создать обращение</button></div></form>`)}
function showDoc(id){const d=state.docs.find(d=>d.id===id)||state.detail?.result?.sources?.find(d=>d.id===id);if(!d)return;modal(d.title,'Источник правил магазина «Листва»',`<div class="source-meta"><span class="badge badge-review">v${esc(d.version)}</span><span>Действует с ${fmtDate(d.effective_from,{day:'numeric',month:'long',year:'numeric'})}</span>${d.effective_to?`<span>До ${fmtDate(d.effective_to)}</span>`:''}</div><div class="modal-prose">${esc(d.text)}<h3 style="font-size:13px;margin-top:24px">Факты для ответа</h3>${Object.entries(d.facts||{}).map(([k,v])=>`<div class="doc-fact"><code style="font-size:9px">${esc(k)}</code><br>${esc(v)}</div>`).join('')}</div><div class="modal-actions"><button class="btn" data-action="close-modal">Закрыть</button></div>`,true)}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function selectTicket(id,workflow=false){state.selected=id;state.tab=workflow?'workflow':'draft';try{state.detail=await request('/tickets/'+id);render();}catch(e){fail(e)}}
async function analyze(fault='none'){if(state.busy||!state.detail)return;const id=state.selected;state.busy=true;render();try{await request(`/tickets/${id}/analyze`,{method:'POST',body:{fault}});await reload();state.tab='draft';toast(state.detail.result?.reason?'Обращение требует ручной проверки':'Черновик готов к проверке');}catch(e){fail(e)}finally{state.busy=false;render()}}
async function review(decision,note=''){const t=state.detail;const text=state.drafts[t.id]??t.result?.draft??'';const button=$(`[data-action="${decision==='approve'?'approve':'escalate'}"]`);if(button)button.disabled=true;try{await request(`/tickets/${t.id}/review`,{method:'POST',body:{decision,text,note,revision:t.revision}});closeModal();await reload();render();toast(decision==='approve'?'Ответ подтверждён. Решение сохранено.':'Обращение передано сотруднику');}catch(e){fail(e);if(button)button.disabled=false}}
async function runFault(fault){closeModal();try{const t=await request('/tickets',{method:'POST',body:{customer:'Анна Смирнова',email:'customer1@example.test',order_id:'1042',channel:'web',priority:'high',subject:`Проверка сбоя · ${{orders_timeout:'API заказов',invalid_model:'ответ модели',missing_sources:'источники'}[fault]}`,message:'Заказ №1042 должен был прийти вчера. Где он и можно ли отменить покупку?'},headers:{'Idempotency-Key':crypto.randomUUID()}});state.selected=t.id;state.filter='all';state.page='tickets';history.replaceState(null,'','#tickets');await reload();await analyze(fault);}catch(e){fail(e)}}

document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-action],a');if(!el)return;if(el.dataset.ticket){await selectTicket(el.dataset.ticket);return;}if(el.dataset.openTicket){state.page='tickets';state.filter='all';history.replaceState(null,'','#tickets');await selectTicket(el.dataset.openTicket,!!el.dataset.workflow);return;}if(el.dataset.filter){state.filter=el.dataset.filter;render();return;}if(el.dataset.tab){state.tab=el.dataset.tab;$('#ticket-detail').innerHTML=detailContent();return;}if(el.dataset.doc){showDoc(el.dataset.doc);return;}if(el.dataset.archive){state.showArchived=el.dataset.archive==='true';render();return;}if(el.dataset.fault){await runFault(el.dataset.fault);return;}const a=el.dataset.action;try{switch(a){case'new':newTicket();break;case'close-modal':closeModal();break;case'clear-search':state.filter='all';state.query='';render();break;case'sort':state.sort=state.sort==='newest'?'priority':'newest';render();break;case'analyze':await analyze();break;case'approve':await review('approve');break;case'escalate':modal('Передать сотруднику','Добавьте контекст для ручной обработки.',`<form id="escalate-form"><label class="field">Причина и комментарий<textarea name="note" required minlength="5" maxlength="1000" placeholder="Что сотруднику нужно проверить?">${esc(reasonNames[state.detail.result?.reason]||'Требуется дополнительная проверка ответа сотрудником.')}</textarea></label><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Отмена</button><button class="btn btn-primary" type="submit">Передать сотруднику</button></div></form>`);break;case'copy-id':await navigator.clipboard.writeText(state.selected);toast('Номер обращения скопирован');break;case'copy-draft':await navigator.clipboard.writeText(state.drafts[state.selected]??(state.detail.reviews||[]).findLast?.(r=>r.decision==='approve')?.text??state.detail.result?.draft??'');toast('Текст ответа скопирован');break;case'refresh':await reload();render();toast('Данные обновлены');break;case'export-trace':download(`${state.selected}-trace.json`,state.detail);break;case'export-knowledge':download('listva-knowledge.json',state.docs);break;case'export-eval':download('supportops-evaluation.json',state.evaluation);break;case'fill-example':{const form=$('#ticket-form');const values={customer:'Анна Смирнова',email:'customer1@example.test',order_id:'1042',subject:'Где заказ и можно ли отменить?',message:'Заказ №1042 должен был прийти вчера. Где он и можно ли отменить покупку?'};for(const [k,v]of Object.entries(values))form.elements[k].value=v;break;}case'activity':state.page='monitoring';location.hash='monitoring';render();break;case'order-info':modal('Данные заказа','Синтетический API магазина. Только просмотр.',`<pre class="code-block">${esc(JSON.stringify(state.detail.result?.order,null,2))}</pre>`,true);break;case'faults':modal('Проверить обработку сбоя','Для сценария будет создано отдельное синтетическое обращение.',`<div class="check-list">${[['orders_timeout','Таймаут API заказов'],['invalid_model','Неверная структура ответа модели'],['missing_sources','Нет необходимых источников']].map(([id,label])=>`<button class="btn" data-fault="${id}">${icon('play')}${label}</button>`).join('')}</div>`);break;case'demo-info':modal('О демонстрации','Рабочий сценарий на синтетических данных.',`<div class="modal-prose">В этом демо можно создавать обращения, готовить ответы, проверять источники, редактировать текст и сохранять review.<br><br>Все изменения хранятся в вашем браузере. Внешний LLM и AWS не подключены. Задержки и экономия времени не симулируются.<br><br>Полная версия проекта содержит FastAPI, LangGraph, PostgreSQL / pgvector, evaluation, Docker, CI/CD и конфигурацию AWS.</div>`);break;case'eval-info':modal('Повторить evaluation','Запуск из корня локального проекта.',`<pre class="code-block">python -m eval.run --split dev
python -m eval.run --split holdout
pytest

# Live-проверка: настройте LLM_* в .env
python -m eval.run --split holdout --live</pre><p class="modal-prose">Dev и holdout разделены. Отчёт сохраняет версии модели, промпта, документов и набора. Любая критическая фактическая ошибка блокирует выпуск.</p>`);break;case'runbook':modal('Восстановление после сбоя','Практический порядок проверки.',`<div class="modal-prose"><b>1. API заказов недоступен</b><br>Проверьте /health/live у mock-orders, сеть и ORDERS_API_URL. Восстановите сервис и нажмите «Повторить анализ».<br><br><b>2. Неверный ответ модели</b><br>Откройте trace и manifest. Проверьте версию промпта и контракт. После двух неудачных попыток обращение остаётся человеку.<br><br><b>3. Неудачный релиз</b><br>AI Guard блокирует релиз с регрессией. ECS circuit breaker откатывает нездоровый deployment. Содержательные ошибки требуют возврата к проверенному image digest.<br><br>Полные команды и проверка восстановления: docs/runbook.md в проекте.</div>`,true);break;case'reset-demo':modal('Сбросить демонстрацию','Все созданные обращения и решения этого демо будут удалены из текущего браузера.',`<div class="modal-actions"><button class="btn" data-action="close-modal">Отмена</button><button class="btn btn-primary" data-action="confirm-reset">Сбросить данные</button></div>`);break;case'confirm-reset':localStorage.removeItem('supportops-demo-v1');location.reload();break;}}catch(err){fail(err)}});
document.addEventListener('input',e=>{if(e.target.id==='ticket-search'){state.query=e.target.value;$('#ticket-items').innerHTML=ticketItems();}if(e.target.id==='draft-text'){state.drafts[state.selected]=e.target.value;}if(e.target.id==='doc-search'){state.docQuery=e.target.value;const cursor=e.target.selectionStart;render();$('#doc-search').focus();$('#doc-search').setSelectionRange(cursor,cursor);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='ticket-form'){const button=form.querySelector('[type="submit"]');button.disabled=true;try{const values=Object.fromEntries(new FormData(form));values.order_id=values.order_id||null;const t=await request('/tickets',{method:'POST',body:values,headers:{'Idempotency-Key':creationKey}});closeModal();state.page='tickets';state.filter='all';state.query='';state.selected=t.id;state.tab='draft';history.replaceState(null,'','#tickets');await reload();render();toast('Обращение создано');}catch(err){fail(err);button.disabled=false}}if(form.id==='escalate-form')await review('escalate',new FormData(form).get('note'));if(form.id==='auth-form'){sessionStorage.setItem('supportops-api-key',new FormData(form).get('key'));try{await reload();render();toast('Подключение установлено');}catch(err){fail(err)}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.page!=='tickets'){state.page='tickets';render()}$('#ticket-search')?.focus();}if(e.key.toLowerCase()==='n'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!e.metaKey&&!e.ctrlKey&&!$('#overlay').children.length){e.preventDefault();newTicket();}if(e.key==='Tab'&&$('#overlay').children.length){const list=[...$('#overlay').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]){state.page=p;render()}});
try{await init();try{await reload()}catch(err){if(err.status===401){state.page='settings';render();toast('Введите ключ доступа к API в настройках',true);}else throw err;}if(state.page!=='settings'){state.page=pages[location.hash.slice(1)]?location.hash.slice(1):'tickets';render();}}catch(e){$('#app').innerHTML=`<div class="error-screen"><h2>Не удалось открыть рабочее пространство</h2><p>${esc(e.message)}</p><p>Проверьте, что сервер SupportOps запущен и доступен.</p><button class="btn" data-action="refresh">${icon('refresh')}Повторить</button></div>`;}
